<p class="eyebrow"><?= $e($t('PRIVATE · READ-ONLY HISTORY')) ?></p><h1><?= $e($snapshot['title']) ?></h1><p><?= $e($t('Saved version')) ?> <?= $e($snapshot['revision']) ?> · <?= $e($snapshot['id']) ?></p><p class="notice"><?= $e($t('This is an earlier declared record, not the current passport. Its content must not be treated as permission for new use.')) ?></p><a href="/dashboard/stories/<?= $e($snapshot['id']) ?>"><?= $e($t('Back to the current record')) ?></a><section class="card"><h2><?= $e($t('Story and context')) ?></h2><p><?= $e($snapshot['creator']['name']) ?> · <?= $e($snapshot['language']) ?> · <?= $e($snapshot['placeCoarse']) ?></p><p class="preserve"><?= $e($snapshot['textBody']) ?></p><p class="preserve"><?= $e($snapshot['contextNote']) ?></p><p><?= $e(\Passport\Copy::SHARING[$snapshot['sharingState']]) ?> · <?= $e($snapshot['sensitivity']) ?></p></section><section class="card"><h2><?= $e($t('Terms, shares and consent at this version')) ?></h2><p><?= $e(\Passport\Copy::PRESETS[$snapshot['license']['preset']]) ?></p><p><?= $e($snapshot['license']['notes']) ?></p><?php foreach ($snapshot['contributors'] as $person): ?><h3><?= $e($person['name']) ?> · <?= $e($person['role']) ?></h3><?php foreach (\Passport\Copy::PURPOSES as $purpose=>$label): ?><span class="badge"><?= $e($label) ?>: <?= $e($t(($person['consents'][$purpose]['granted']??false)?'Granted':'Not granted')) ?></span><?php endforeach ?><?php endforeach ?><?php foreach ($snapshot['shares'] as $share): ?><p><?= $e(array_values(array_filter($snapshot['contributors'],static fn(array $p):bool=>$p['id']===$share['contributorId']))[0]['name']) ?> · <?= $e(number_format($share['bps']/100,2)) ?>%</p><?php endforeach ?><p><?= $e($snapshot['preferredCredit']) ?></p></section>
